import React,{useState} from 'react';
import {chapterPlacement,placementIntent} from '../../../domain/event-placement.js';
import {placementArguments,placementRequest} from '../../../domain/placement-request.js';
import {useResource} from '../../shared/state.js';
import {useWritingRequest} from '../../shared/writing-request.js';
import {ResourceState,SaveBar} from '../../shared/ui.jsx';
import {Modal} from '../../shared/preferences.tsx';
export function EventPlacementEditor({request,change,close,call,novelId,run,busy,saved}){
 const resource=useResource(()=>call('writing.event.get',{novelId,id:request.id}),[call,novelId,request.id,request.expectedRevision]),write=useWritingRequest(call),[error,setError]=useState('');
 const old=resource.value,stale=old?.revision!==request.expectedRevision,chapters=request.chapters;
 let plan,invalid='';try{if(request.view==='narration')plan=chapterPlacement(chapters,request.source,request);}catch(e){invalid=e.message;}
 const label=id=>chapters.find(c=>c.id===id)?.title||'缺失章节',setStart=id=>{if(request.operation==='move'){const index=chapters.findIndex(c=>c.id===id);change({...request,...placementIntent(chapters,request.source,'move',index)});}else change({...request,startChapterId:id});},setEnd=id=>change({...request,endChapterId:id});
 const recheck=()=>run(async()=>{try{const board=await call('writing.board.get',{novelId});change(placementRequest(board,request.id,request.view,request.view==='story'?{operation:'move',beforeEventId:request.beforeEventId}:{operation:request.operation,startChapterId:request.startChapterId,endChapterId:request.endChapterId}));resource.retry();setError('');}catch(e){setError(e.message);throw e;}});
 const save=()=>run(async()=>{setError('');try{const result=await write('writing.event.place',{novelId,...placementArguments(request),confirmed:true,reason:request.view==='story'?'作者拖动故事顺序，保持叙述顺序和日期':'作者调整事件章节位置，新增引用不复制正文依据'});saved(result);}catch(e){setError(e.message);throw e;}});
 const targetPresent=request.view!=='story'||request.beforeEventId===null||request.story.some(e=>e.id===request.beforeEventId&&e.id!==request.id);
 return <Modal title="调整事件位置" close={close} className="chapter-materials-modal"><h3>{request.source.title}</h3><p className="muted">{request.view==='story'?'修改故事先后；日期与正文章节位置保持。':'修改章节呈现位置；原文、人物出场与伏笔依据保持。'}</p><ResourceState resource={resource}>{old&&<><div className="structure-form">{request.view==='story'?<label>放在事件之前<select aria-label="事件的新故事位置" value={request.beforeEventId||''} onChange={e=>change({...request,beforeEventId:e.target.value||null})}><option value="">最后一个事件之后</option>{request.story.filter(e=>e.id!==request.id).map(e=><option key={e.id} value={e.id}>{e.title}</option>)}</select></label>:<><label>调整方式<select aria-label="事件位置调整方式" value={request.operation} onChange={e=>{const operation=e.target.value;if(operation==='move'){const index=chapters.findIndex(c=>c.id===request.startChapterId);change({...request,...placementIntent(chapters,request.source,operation,index)});}else change({...request,operation:'range'});}}><option value="move">整体移动，保留跨度与间隔</option><option value="range">指定连续范围</option>{['resize-start','resize-end'].includes(request.operation)&&<option value={request.operation}>{request.operation==='resize-start'?'调整开始章':'调整结束章'}</option>}</select></label><label>开始章<select aria-label="事件开始章" disabled={request.operation==='resize-end'} value={request.startChapterId||''} onChange={e=>setStart(e.target.value)}>{chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>结束章<select aria-label="事件结束章" disabled={request.operation==='move'||request.operation==='resize-start'} value={request.endChapterId||''} onChange={e=>setEnd(e.target.value)}>{chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>{plan&&<div className="placement-summary"><strong>{label(request.startChapterId)} → {label(request.endChapterId)}</strong>{plan.added.length>0&&<p>新增关联：{plan.added.map(label).join('、')}。原文依据留空。</p>}{plan.removed.length>0&&<p>移出当前呈现：{plan.removed.map(label).join('、')}。原引用与依据保留在历史里。</p>}{plan.kept.length>0&&<p>继续保留：{plan.kept.map(label).join('、')}。</p>}{!plan.changed&&<p>位置未变化，无需保存。</p>}</div>}</>}
 {stale&&<p role="alert">事件已有新版本，目标位置草稿仍在。请核对最新版本后保存。</p>}</div><SaveBar dirty={request.view==='story'||!!plan?.changed} {...{busy}} error={error} invalid={stale?'核对最新事件版本':invalid||(!targetPresent?'目标事件已移除':null)} label="保存位置" onSave={save}/>{(stale||error)&&<button disabled={busy} onClick={recheck}>保留目标位置并核对最新版本</button>}</>}</ResourceState></Modal>;
}
